enum AccountType { bank, cash, creditCard, savings }
enum TransactionType { income, expense, transfer }
class FinanceAccount { final String id,name; final AccountType type; final double openingBalance; final double? creditLimit; const FinanceAccount({required this.id,required this.name,required this.type,required this.openingBalance,this.creditLimit}); Map<String,dynamic> toJson()=>{'id':id,'name':name,'type':type.name,'openingBalance':openingBalance,'creditLimit':creditLimit}; factory FinanceAccount.fromJson(Map<String,dynamic> j)=>FinanceAccount(id:j['id'],name:j['name'],type:AccountType.values.byName(j['type']),openingBalance:(j['openingBalance'] as num).toDouble(),creditLimit:(j['creditLimit'] as num?)?.toDouble()); }
class FinanceTransaction { final String id; final TransactionType type; final double amount; final String category,description,accountId; final String? destinationAccountId; final DateTime date; const FinanceTransaction({required this.id,required this.type,required this.amount,required this.category,required this.description,required this.accountId,this.destinationAccountId,required this.date}); Map<String,dynamic> toJson()=>{'id':id,'type':type.name,'amount':amount,'category':category,'description':description,'accountId':accountId,'destinationAccountId':destinationAccountId,'date':date.toIso8601String()}; factory FinanceTransaction.fromJson(Map<String,dynamic> j)=>FinanceTransaction(id:j['id'],type:TransactionType.values.byName(j['type']),amount:(j['amount'] as num).toDouble(),category:j['category'],description:j['description'],accountId:j['accountId'],destinationAccountId:j['destinationAccountId'],date:DateTime.parse(j['date'])); }
class Budget { final String id,category; final double limit; const Budget({required this.id,required this.category,required this.limit}); Map<String,dynamic> toJson()=>{'id':id,'category':category,'limit':limit}; factory Budget.fromJson(Map<String,dynamic> j)=>Budget(id:j['id'],category:j['category'],limit:(j['limit'] as num).toDouble()); }
class SavingsGoal { final String id,name; final double target,current; final DateTime? targetDate; const SavingsGoal({required this.id,required this.name,required this.target,required this.current,this.targetDate}); Map<String,dynamic> toJson()=>{'id':id,'name':name,'target':target,'current':current,'targetDate':targetDate?.toIso8601String()}; factory SavingsGoal.fromJson(Map<String,dynamic> j)=>SavingsGoal(id:j['id'],name:j['name'],target:(j['target'] as num).toDouble(),current:(j['current'] as num).toDouble(),targetDate:j['targetDate']==null?null:DateTime.parse(j['targetDate'])); SavingsGoal copyWith({double? current})=>SavingsGoal(id:id,name:name,target:target,current:current??this.current,targetDate:targetDate); }
class Debt { final String id,name; final double balance,apr,minimumPayment; final DateTime? dueDate; const Debt({required this.id,required this.name,required this.balance,required this.apr,required this.minimumPayment,this.dueDate}); Map<String,dynamic> toJson()=>{'id':id,'name':name,'balance':balance,'apr':apr,'minimumPayment':minimumPayment,'dueDate':dueDate?.toIso8601String()}; factory Debt.fromJson(Map<String,dynamic> j)=>Debt(id:j['id'],name:j['name'],balance:(j['balance'] as num).toDouble(),apr:(j['apr'] as num).toDouble(),minimumPayment:(j['minimumPayment'] as num).toDouble(),dueDate:j['dueDate']==null?null:DateTime.parse(j['dueDate'])); }
class RecurringPayment { final String id,name,category,accountId; final double amount; final int dayOfMonth; final bool isExpense,active; const RecurringPayment({required this.id,required this.name,required this.category,required this.accountId,required this.amount,required this.dayOfMonth,this.isExpense=true,this.active=true}); Map<String,dynamic> toJson()=>{'id':id,'name':name,'category':category,'accountId':accountId,'amount':amount,'dayOfMonth':dayOfMonth,'isExpense':isExpense,'active':active}; factory RecurringPayment.fromJson(Map<String,dynamic> j)=>RecurringPayment(id:j['id'],name:j['name'],category:j['category'],accountId:j['accountId'],amount:(j['amount'] as num).toDouble(),dayOfMonth:j['dayOfMonth'],isExpense:j['isExpense']??true,active:j['active']??true); }
